import numpy as np
lines=open('initial_complex_rot.xyz').read().splitlines()[2:]
atoms=[(l.split()[0],np.array(list(map(float,l.split()[1:4])))) for l in lines]
# cp 1..35, tri 36..72, rh0
def dist(i,j): return float(np.linalg.norm(atoms[i][1]-atoms[j][1]))
for include_h in [False, True]:
    pairs=[]; mind=999; pair=None
    for i in range(1,36):
        if not include_h and atoms[i][0]=='H': continue
        for j in range(36,len(atoms)):
            if not include_h and atoms[j][0]=='H': continue
            d=dist(i,j)
            if d<mind: mind=d; pair=(i,atoms[i][0],j,atoms[j][0])
            if d<(2.2 if not include_h else 1.5): pairs.append((d,i,atoms[i][0],j,atoms[j][0]))
    pairs.sort()
    print('include_h',include_h,'mind',mind,pair,'nclose',len(pairs))
    print(pairs[:30])
# print cp local atom identities for indices around 29-31 and tri 31-36
for idx in range(1,36):
    if idx in [13,14,15,16,17,18,19,20,29,30,31,32,33,34,35]:
        print('cp final idx',idx,'local',idx-1,atoms[idx][0],atoms[idx][1])
for idx in range(36,73):
    if idx-36 in [0,1,2,14,15,16,17,18,31,32,33,34,35,36]:
        print('tri final idx',idx,'local',idx-36,atoms[idx][0],atoms[idx][1])
