import numpy as np
lines=open('optimized_complex.xyz').read().splitlines()[2:]
atoms=[(l.split()[0],np.array(list(map(float,l.split()[1:4])))) for l in lines]
for ni in [36,39,46]:
    close=[]
    for i,(s,p) in enumerate(atoms):
        d=float(np.linalg.norm(p-atoms[ni][1]))
        if d<1.2:
            close.append((i,s,round(d,3)))
    print('N',ni,'close<1.2',close)
# print OH and NH hydrogens
for i,(s,p) in enumerate(atoms):
    if s=='O':
        print('O',i,'close',[(j,atoms[j][0],round(float(np.linalg.norm(atoms[j][1]-p)),3)) for j in range(len(atoms)) if float(np.linalg.norm(atoms[j][1]-p))<1.2])
